$requirements$;

create temp table winter_challah_review_bank (
  id uuid primary key, week smallint not null check (week between 1 and 4),
  topic text not null, prompt text not null, kind public.review_question_kind not null,
  choices jsonb not null, correct_choice_index smallint not null,
  explanation text not null, is_model_question boolean not null,
  check (jsonb_typeof(choices) = 'array'),
  check ((kind = 'true_false' and choices = '["True","False"]'::jsonb)
      or (kind = 'multiple_choice' and jsonb_array_length(choices) = 4)),
  check (correct_choice_index >= 0 and correct_choice_index < jsonb_array_length(choices))
) on commit drop;

